// CoreProductionScheduleServiceServer is the server API for CoreProductionScheduleService service.
// All implementations must embed UnimplementedCoreProductionScheduleServiceServer
// for forward compatibility.
type CoreProductionScheduleServiceServer interface {
	// PreviewProductionSchedule runs the solver and returns the plan without persisting it.
	PreviewProductionSchedule(context.Context, *PreviewProductionScheduleRequest) (*PreviewProductionScheduleResponse, error)
	// GenerateProductionSchedule solves and persists a new draft version.
	GenerateProductionSchedule(context.Context, *GenerateProductionScheduleRequest) (*GenerateProductionScheduleResponse, error)
	// PreviewRegenerateProductionSchedule says what a re-solve would change about a draft,
	// without changing it.
	PreviewRegenerateProductionSchedule(context.Context, *RegenerateProductionScheduleRequest) (*PreviewRegenerateProductionScheduleResponse, error)
	// RegenerateProductionSchedule re-solves a draft in place, keeping its version number.
	RegenerateProductionSchedule(context.Context, *RegenerateProductionScheduleRequest) (*RegenerateProductionScheduleResponse, error)
	// GetProductionSchedule returns one version by ID.
	GetProductionSchedule(context.Context, *GetProductionScheduleRequest) (*GetProductionScheduleResponse, error)
	// GetCurrentProductionSchedule returns the published version covering today.
	GetCurrentProductionSchedule(context.Context, *GetCurrentProductionScheduleRequest) (*GetProductionScheduleResponse, error)
	// ListProductionSchedules returns a paginated list of versions.
	ListProductionSchedules(context.Context, *ListProductionSchedulesRequest) (*ListProductionSchedulesResponse, error)
	// ListProductionScheduleLines returns the planned campaigns for a version.
	ListProductionScheduleLines(context.Context, *ListProductionScheduleLinesRequest) (*ListProductionScheduleLinesResponse, error)
	// ListProductionScheduleItemPolicies returns the per-item policy snapshot for a version.
	ListProductionScheduleItemPolicies(context.Context, *ListProductionScheduleItemPoliciesRequest) (*ListProductionScheduleItemPoliciesResponse, error)
	// ListProductionScheduleFinishedPolicies returns the per-finished-SKU decomposition of
	// the pooled constraint buffers.
	ListProductionScheduleFinishedPolicies(context.Context, *ListProductionScheduleFinishedPoliciesRequest) (*ListProductionScheduleFinishedPoliciesResponse, error)
	// ListProductionScheduleFinishingLines returns stage two: how many of which finished
	// good to make from the knitted parts, week by week.
	ListProductionScheduleFinishingLines(context.Context, *ListProductionScheduleFinishingLinesRequest) (*ListProductionScheduleFinishingLinesResponse, error)
	// GetProductionScheduleSettings returns the merchant's planning assumptions.
	GetProductionScheduleSettings(context.Context, *GetProductionScheduleSettingsRequest) (*GetProductionScheduleSettingsResponse, error)
	// UpdateProductionScheduleSettings replaces the merchant's planning assumptions.
	UpdateProductionScheduleSettings(context.Context, *UpdateProductionScheduleSettingsRequest) (*GetProductionScheduleSettingsResponse, error)
	// ListProductionScheduleResourceSettings returns per-resource overrides.
	ListProductionScheduleResourceSettings(context.Context, *ListProductionScheduleResourceSettingsRequest) (*ListProductionScheduleResourceSettingsResponse, error)
	// UpsertProductionScheduleResourceSetting writes one per-resource override.
	UpsertProductionScheduleResourceSetting(context.Context, *UpsertProductionScheduleResourceSettingRequest) (*UpsertProductionScheduleResourceSettingResponse, error)
	// DeleteProductionScheduleResourceSetting removes one per-resource override.
	DeleteProductionScheduleResourceSetting(context.Context, *DeleteProductionScheduleResourceSettingRequest) (*emptypb.Empty, error)
	// ListFulfillmentRecommendations works out which SKUs should be built to order.
	ListFulfillmentRecommendations(context.Context, *ListFulfillmentRecommendationsRequest) (*ListFulfillmentRecommendationsResponse, error)
	// ApplyFulfillmentRecommendations writes the recommended policy onto the named items.
	ApplyFulfillmentRecommendations(context.Context, *ApplyFulfillmentRecommendationsRequest) (*ListFulfillmentRecommendationsResponse, error)
	// ListProductionScheduleItemSettings returns per-item planning overrides.
	ListProductionScheduleItemSettings(context.Context, *ListProductionScheduleItemSettingsRequest) (*ListProductionScheduleItemSettingsResponse, error)
	// GetProductionScheduleItemSetting returns one item's planning override.
	GetProductionScheduleItemSetting(context.Context, *GetProductionScheduleItemSettingRequest) (*ProductionScheduleItemSettingResponse, error)
	// UpsertProductionScheduleItemSetting writes one item's planning override.
	UpsertProductionScheduleItemSetting(context.Context, *UpsertProductionScheduleItemSettingRequest) (*ProductionScheduleItemSettingResponse, error)
	// DeleteProductionScheduleItemSetting removes one item's planning override.
	DeleteProductionScheduleItemSetting(context.Context, *DeleteProductionScheduleItemSettingRequest) (*emptypb.Empty, error)
	// ListProductionScheduleAtRiskOrders returns the commitments a version does not meet.
	ListProductionScheduleAtRiskOrders(context.Context, *ListProductionScheduleAtRiskOrdersRequest) (*ListProductionScheduleAtRiskOrdersResponse, error)
	// QuotePromiseDate says the earliest date the published plan could ship a quantity.
	QuotePromiseDate(context.Context, *QuotePromiseDateRequest) (*QuotePromiseDateResponse, error)
	// ListProductionScheduleDerivedLines returns derived downstream department work.
	ListProductionScheduleDerivedLines(context.Context, *ListProductionScheduleDerivedLinesRequest) (*ListProductionScheduleDerivedLinesResponse, error)
	// ListScheduleDeviationTypes returns the global deviation taxonomy.
	ListScheduleDeviationTypes(context.Context, *ListScheduleDeviationTypesRequest) (*ListScheduleDeviationTypesResponse, error)
	// ListProductionScheduleDeviations returns the append-only log of hand changes.
	ListProductionScheduleDeviations(context.Context, *ListProductionScheduleDeviationsRequest) (*ListProductionScheduleDeviationsResponse, error)
	// CreateProductionScheduleLine adds a campaign by hand.
	CreateProductionScheduleLine(context.Context, *CreateProductionScheduleLineRequest) (*CreateProductionScheduleLineResponse, error)
	// UpdateProductionScheduleLine edits a campaign.
	UpdateProductionScheduleLine(context.Context, *UpdateProductionScheduleLineRequest) (*UpdateProductionScheduleLineResponse, error)
	// DeleteProductionScheduleLine removes a campaign.
	DeleteProductionScheduleLine(context.Context, *DeleteProductionScheduleLineRequest) (*emptypb.Empty, error)
	// PublishProductionSchedule freezes the first weeks and supersedes what it replaces.
	PublishProductionSchedule(context.Context, *PublishProductionScheduleRequest) (*PublishProductionScheduleResponse, error)
	// ReleaseProductionScheduleWeek turns one planned week into a production run.
	ReleaseProductionScheduleWeek(context.Context, *ReleaseProductionScheduleWeekRequest) (*ReleaseProductionScheduleWeekResponse, error)
	// PreviewReleaseProductionScheduleWeek says what releasing a week would create.
	PreviewReleaseProductionScheduleWeek(context.Context, *PreviewReleaseProductionScheduleWeekRequest) (*ReleaseProductionScheduleWeekPreviewResponse, error)
	// ArchiveProductionSchedule retires a version.
	ArchiveProductionSchedule(context.Context, *ArchiveProductionScheduleRequest) (*ArchiveProductionScheduleResponse, error)
	// DeleteProductionSchedule removes a draft version.
	DeleteProductionSchedule(context.Context, *DeleteProductionScheduleRequest) (*emptypb.Empty, error)
	// Operating calendars: the days a plant tenders freight and a customer's dock accepts it,
	// which every ship-by commitment is resolved against. They live on this service because the
	// account settings that select them are the same settings the solver is configured with.
	ListOperatingCalendars(context.Context, *ListOperatingCalendarsRequest) (*ListOperatingCalendarsResponse, error)
	GetOperatingCalendar(context.Context, *GetOperatingCalendarRequest) (*OperatingCalendarInfo, error)
	CreateOperatingCalendar(context.Context, *CreateOperatingCalendarRequest) (*OperatingCalendarInfo, error)
	UpdateOperatingCalendar(context.Context, *UpdateOperatingCalendarRequest) (*OperatingCalendarInfo, error)
	DeleteOperatingCalendar(context.Context, *DeleteOperatingCalendarRequest) (*emptypb.Empty, error)
	ListOperatingCalendarClosures(context.Context, *ListOperatingCalendarClosuresRequest) (*ListOperatingCalendarClosuresResponse, error)
	CreateOperatingCalendarClosure(context.Context, *CreateOperatingCalendarClosureRequest) (*OperatingCalendarClosureInfo, error)
	DeleteOperatingCalendarClosure(context.Context, *DeleteOperatingCalendarClosureRequest) (*emptypb.Empty, error)
	mustEmbedUnimplementedCoreProductionScheduleServiceServer()
}

